 (269845,"remember (zakar, negated)","action","the fathers","fail to remember","God's steadfast love",IB,"paired with not considering, and with rebelling","v7: 'they did not REMEMBER (zakar) the abundance of your steadfast love' - the forgetting of God's love that bred rebellion."),
 (269848,"rebel (marah)","action","the fathers","rebel","against God at the sea",GOD,"paired with the failure to remember","v7: 'but REBELLED (marah) by the sea, at the Red Sea' - the first act of the catalogue, defiance at the very edge of deliverance."),
 (269595,"believe (aman)","disposition","the fathers","believe","God's words",GOD,"paired with singing his praise","v12: 'Then they BELIEVED (aman) his words' - the flash of faith after the sea's deliverance, belief that would not last."),
