 (269630,"worship (shachah)","action","the fathers","worship","a metal image",IB,"paired with exchanging the glory","v19: 'and WORSHIPED (shachah) a metal image' - the calf-worship at Horeb, the exchange of the living God for an idol."),
 (269640,"exchange (mur)","action","the fathers","exchange","the glory of God for an ox-image",IB,"paired with worshiping the calf","v20: 'They EXCHANGED (mur) the glory of God for the image of an ox' - the fatal swap, the Creator traded for a grass-eating beast."),
 (307456,"forget (shakach)","action","the fathers","forget","God their Saviour",IB,"paired with worshiping the calf","v21: 'They FORGOT (shakach) God, their Saviour, who had done great things in Egypt' - the forgetting of the very God who redeemed them."),
