 (269670,"faith (aman, negated)","disposition","the fathers","have no faith","in God's promise",GOD,"paired with despising the land","v24: 'having no FAITH (aman) in his promise' - the unbelief that could not trust God to give the land."),
 (269673,"murmur (ragan)","action","the fathers","murmur / grumble","in their tents",GOD,"paired with not obeying","v25: 'They MURMURED (ragan) in their tents' - the grumbling of the people, discontent turned to complaint against God."),
 (269676,"obey (shama, negated)","action","the fathers","fail to obey","the voice of the LORD",GOD,"paired with murmuring","v25: 'and did not OBEY (shama) the voice of the LORD' - the disobedience behind the murmuring."),
